<?php
declare(strict_types=1);namespace App\Command;
use App\Imperium\Runtime\Conscription\OperationalProfileQualificationService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:conscription:qualify-operational-profile',description:'Install and qualify one exact Imperator-approved Profile for operational assembly.')]
final class ConscriptionQualifyOperationalProfileCommand extends Command{public function __construct(private readonly OperationalProfileQualificationService$s){parent::__construct();}protected function configure():void{$this->addArgument('profile-approval-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->qualify((string)$i->getArgument('profile-approval-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>PROFILE_OPERATIONALLY_QUALIFIED</info> '.$r['qualification_id']);return self::SUCCESS;}}
